export type RootStackParamList = {
  Beranda: undefined;                         // tidak butuh parameter
  DetailProduk: { produkId: string };          // wajib bawa produkId
  Keranjang: undefined;
  Checkout: { kodePromo?: string };            // parameter opsional
  Pembayaran: { pesananId: string; total: number };
};

import { createNativeStackNavigator } from '@react-navigation/native-stack';
import type { RootStackParamList } from '../types/navigation';

const Stack = createNativeStackNavigator<RootStackParamList>();

export function RootNavigator() {
  return (
    <Stack.Navigator>
      <Stack.Screen name="Beranda" component={LayarBeranda} />
      <Stack.Screen name="DetailProduk" component={LayarDetailProduk} />
      <Stack.Screen name="Keranjang" component={LayarKeranjang} />
      <Stack.Screen name="Checkout" component={LayarCheckout} />
      <Stack.Screen name="Pembayaran" component={LayarPembayaran} />
      {/* <Stack.Screen name="Profil" ... /> ❌ 'Profil' tidak ada di peta */}
    </Stack.Navigator>
  );
}

