import type { NativeStackScreenProps } from '@react-navigation/native-stack';
import type { RootStackParamList } from '../types/navigation';
import { View, Text } from 'react-native';

type Props = NativeStackScreenProps<RootStackParamList, 'DetailProduk'>;

export function LayarDetailProduk({ route, navigation }: Props) {
  const { produkId } = route.params;   // bertipe string, dijamin ada
  const produk = useProduk(produkId);

  if (!produk) return <Memuat />;

  return (
    <View style={{ padding: 16, gap: 12 }}>
      <Text style={{ fontSize: 20, fontWeight: '600' }}>{produk.nama}</Text>
      <Text>Rp {produk.harga.toLocaleString('id-ID')}</Text>

      <TombolUtama
        label="Beli Sekarang"
        onTekan={() => navigation.navigate('Checkout', {})}
      />
    </View>
  );
}

// route.params.kodePromo  ❌ tidak ada di parameter DetailProduk

import { useEffect } from 'react';

export function LayarDetailProduk({ route, navigation }: Props) {
  const { produkId } = route.params;
  const produk = useProduk(produkId);

  useEffect(() => {
    navigation.setOptions({ title: produk?.nama ?? 'Memuat...' });
  }, [navigation, produk]);

  // navigation.setOptions juga bertipe — opsi yang tidak dikenal ditolak
  // navigation.setOptions({ judul: 'x' })  ❌
}

