import { useNavigation } from '@react-navigation/native';
import type { NativeStackNavigationProp } from '@react-navigation/native-stack';
import type { RootStackParamList } from '../types/navigation';

type NavigasiProduk = NativeStackNavigationProp<RootStackParamList, 'Beranda'>;

export function KartuProduk({ produk }: { produk: Produk }) {
  const navigation = useNavigation<NavigasiProduk>();

  return (
    <Pressable onPress={() => navigation.navigate('DetailProduk', { produkId: produk.id })}>
      <Text>{produk.nama}</Text>
    </Pressable>
  );
}

// src/types/navigation.ts
export type RootStackParamList = {
  Beranda: undefined;
  DetailProduk: { produkId: string };
  Keranjang: undefined;
};

// Deklarasi global: memberi tahu React Navigation peta bawaan aplikasi ini
declare global {
  namespace ReactNavigation {
    interface RootParamList extends RootStackParamList {}
  }
}

import { useNavigation } from '@react-navigation/native';

export function KartuProduk({ produk }: { produk: Produk }) {
  const navigation = useNavigation();   // sudah tahu peta aplikasi

  return (
    <Pressable onPress={() => navigation.navigate('DetailProduk', { produkId: produk.id })}>
      <Text>{produk.nama}</Text>
    </Pressable>
  );
}

