import { useRoute } from '@react-navigation/native';
import type { RouteProp } from '@react-navigation/native';
import type { RootStackParamList } from '../types/navigation';

type RouteDetail = RouteProp<RootStackParamList, 'DetailProduk'>;

export function TombolBagikan() {
  const route = useRoute<RouteDetail>();
  const { produkId } = route.params;   // bertipe string

  return <Pressable onPress={() => bagikan(produkId)}><Text>Bagikan</Text></Pressable>;
}
